import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, expect, it } from "vitest";
import fixtures from "./fixtures/decisionResponses.json";
import { nemotronResponseSchema } from "@/types/nemotron";
import { explainDecision } from "@/lib/decisionExplanation";
import { NemotronResult } from "@/components/chat/NemotronResult";

// Fixtures generated by run_agent with the real engine and synthetic test records.
const cases = Object.fromEntries(Object.entries(fixtures).map(([key, value]) => [key, nemotronResponseSchema.parse(value)]));
afterEach(cleanup);

it("puts negative cash and cushion breaches first, with a verified later alternative", () => {
  const copy = explainDecision(cases["negative"]!);
  expect(copy.headline).toBe("I wouldn't buy this right now.");
  expect(copy.reasons.join(" ")).toContain("−$100");
  expect(copy.alternatives[0]).toContain("Nov 16");
  expect(copy.alternatives[0]).toContain("has not been stress-tested");
  expect(explainDecision(cases["cushion_breach"]!).headline).toBe("I'd wait before buying this.");
});

it("distinguishes an ordinary pass from failed what-if tests without promising later safety", () => {
  const copy = explainDecision(cases["stress_failure"]!);
  expect(copy.headline).toBe("I'd be cautious about buying this.");
  expect(copy.reasons.join(" ")).toMatch(/If things go as expected/);
  expect(copy.reasons.join(" ")).toMatch(/unexpected bill/);
  expect(copy.alternatives.join(" ")).not.toMatch(/Consider .* instead/);
});

it("does not treat missing obligations or budgets as evidence of affordability", () => {
  const copy = explainDecision(cases["unknown_schedule"]!);
  expect(copy.headline).toMatch(/don't have enough information/);
  expect(copy.reasons.join(" ")).toMatch(/don't have upcoming bills or income/);
  for (const response of Object.values(cases)) {
    const result = explainDecision(response);
    expect(result.limitation).toContain("Category budgets and protected savings are unknown");
    expect(result.reasons.length).toBeLessThanOrEqual(3);
    expect(result.alternatives.length).toBeLessThanOrEqual(2);
    expect(result.headline).not.toMatch(/affordable|safe to buy/i);
  }
});

it("uses only returned balances, reserves and tested dates in its advice", () => {
  for (const response of Object.values(cases)) {
    const copy = explainDecision(response);
    const text = [...copy.reasons, ...copy.alternatives].join(" ");
    const allowedAmounts = new Set([response.passport.reserve, ...response.scenarios.map(s => s.forecast.minimum_balance)].map(value => Math.abs(Number(value))));
    for (const match of text.matchAll(/\$([\d,]+(?:\.\d{2})?)/g)) {
      expect(allowedAmounts.has(Number(match[1]!.replaceAll(",", "")))).toBe(true);
    }
    if (copy.alternatives.some(a => a.startsWith("Consider "))) {
      expect(response.safe_purchase_dates.length).toBeGreaterThan(0);
      expect(response.scenarios.find(s => s.name === "purchase")!.maintains_reserve).toBe(false);
    }
  }
});

it.each(["model_unavailable", "model_protocol_failed"] as const)("keeps %s transparent and evidence accessible", async reason => {
  const response = structuredClone(cases["negative"]!);
  response.fallback_reason = reason;
  render(<NemotronResult response={response} />);
  expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent("I wouldn't buy this right now.");
  expect(screen.getByText("Deterministic fallback")).toBeInTheDocument();
  expect(screen.queryByRole("table")).not.toBeInTheDocument();
  fireEvent.click(screen.getByText("Explore the details"));
  expect(await screen.findByRole("table")).toBeInTheDocument();
  expect(screen.getByText(reason === "model_unavailable" ? /Nemotron was unavailable/ : /investigation was incomplete/)).toBeInTheDocument();
});

it("answers Why and alternatives using existing evidence without a model call", () => {
  render(<NemotronResult response={cases["negative"]!} />);
  fireEvent.click(screen.getByRole("button", { name: "Why?" }));
  expect(screen.queryByRole("region", { name: "What you can do instead" })).not.toBeInTheDocument();
  expect(screen.getByText(/No new model call or calculation/)).toBeInTheDocument();
  fireEvent.click(screen.getByRole("button", { name: "What should I do instead?" }));
  expect(screen.getByText(/Consider Nov 16/)).toBeInTheDocument();
});
